contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address u) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(u != address(this), "must target a non-caller address");
        require(address(this).balance >= amount, "not enough balance");

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterCaller = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterOther = c.getBalance(u); if (__ESBMC_reverted()) return;

        assert(afterCaller == amount && afterOther == 0);
    }

    receive() external payable {}
}

